    /// <summary>Iniciais para o ícone de reserva (ex.: "Visual Studio Code" → "VS", "WinRAR" → "WR", "7-Zip" → "7Z").</summary>
    public static string Initials(string title)
    {
        var words = title.Split(new[] { ' ', '-', '.', '+', '(', ')' }, StringSplitOptions.RemoveEmptyEntries)
            .Where(w => char.IsLetterOrDigit(w[0])).ToList();
        if (words.Count >= 2) return string.Concat(char.ToUpperInvariant(words[0][0]), char.ToUpperInvariant(words[1][0]));
        string w0 = words.Count == 1 ? words[0] : title;
        var caps = w0.Where(char.IsUpper).Take(2).ToList();
        if (caps.Count == 2) return new string(caps.ToArray());
        return w0.Length >= 2 ? string.Concat(char.ToUpperInvariant(w0[0]), char.ToLowerInvariant(w0[1])) : w0.ToUpperInvariant();
    }

